/**
 * Typed errors surfaced to Kotlin as exceptions.
 */
sealed class LibraryException: kotlin.Exception() {
    
    /**
     * A path, query, identifier or limit was rejected before any work.
     */
    class InvalidInput(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The pack claims official origin; signatures are not verifiable yet.
     */
    class UnsignedOfficialPack(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The user has not accepted installing this custom pack.
     */
    class ConfirmationRequired(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The pack or snapshot failed integrity or layout verification.
     */
    class VerificationFailed(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    class AlreadyInstalled(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * No snapshot is active, or the requested one is not installed.
     */
    class NotInstalled(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * Packs with media cannot be installed yet.
     */
    class MediaNotSupported(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * Filesystem or database failure.
     */
    class Storage(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The snapshot is active; activate another before removing it.
     */
    class SnapshotActive(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The app-side pack source failed while being read.
     */
    class SourceFailed(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LibraryException> {
        override fun lift(error_buf: RustBuffer.ByValue): LibraryException = FfiConverterTypeLibraryError.lift(error_buf)
    }

    
}

